using System;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;
public static class B4OcclusionSettings {
 public static object Detach(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");var obj=(UnityEngine.Object)typeof(StaticOcclusionCulling).GetProperty("occlusionCullingSettings",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).GetValue(null);var so=new SerializedObject(obj);var data=so.FindProperty("m_OcclusionCullingData");if(data==null)throw new Exception("Occlusion reference unavailable");string previous=AssetDatabase.GetAssetPath(data.objectReferenceValue);data.objectReferenceValue=null;so.ApplyModifiedPropertiesWithoutUndo();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(s);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(s);return new{detachedFromB4=previous,existingAssetPreserved=string.IsNullOrEmpty(previous)||AssetDatabase.LoadMainAssetAtPath(previous)!=null};}
 public static object Inspect(){return new{methods=typeof(StaticOcclusionCulling).GetMethods(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Select(m=>m.ToString()).ToArray(),types=AppDomain.CurrentDomain.GetAssemblies().Where(a=>a.GetName().Name.StartsWith("Unity")).SelectMany(a=>a.GetTypes()).Where(t=>t.Name.Contains("OcclusionCullingSettings")).Select(t=>new{name=t.FullName,methods=t.GetMethods(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Select(m=>m.ToString()).ToArray()}).ToArray()};}}
